public class OPFChecker30Test {

    @Mock
    public OFItem item;

    @Mock
    public OPFHandler handler;

    private OPFChecker30 subject;

    @Before
    public void setup() {
        subject = new OPFChecker30();
    }

    @Test
    public void testInitHandler() {
        try {
            subject.initHandler();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    @Test
    public void testCheckPackage() {
        boolean result = subject.checkPackage();
        Mockito.when(subject.getValidationResult()).thenReturn(result);
        assertTrue(subject.getValidationResult());
    }

    @Test
    public void testCheckContent() {
        boolean result = subject.checkContent();
        Mockito.when(subject.getValidationResult()).thenReturn(result);
        assertFalse(subject.getValidationResult());
    }

    @Test
    public void testCheckItem() {
        Mockito.when(item.getType()).thenReturn("test");
        boolean result = subject.checkItem(item, handler);
        Mockito.when(handler.validate(item)).thenReturn(true);
        assertTrue(result);
    }

    @Test
    public void testIsAudioType() {
        String type = "audio";
        boolean result = isAudioType(type);
        assertTrue(result.equals("audio"));
    }

    private boolean isAudioType(String type) {
        return type.equals("audio");
    }
}
